import re

template = input()
k = int(input())
values = {}
for _ in range(k):
    name, value = input().split('=', 1)
    values[name] = value

parts = re.split(r'(\{\{|\}\}|\{[A-Za-z_][A-Za-z0-9_]*\})', template)
rendered, missing, used = [], [], set()
for part in parts:
    if part == '{{':
        rendered.append('{')
    elif part == '}}':
        rendered.append('}')
    elif re.fullmatch(r'\{[A-Za-z_][A-Za-z0-9_]*\}', part):
        name = part[1:-1]
        if name in values:
            used.add(name)
            rendered.append(values[name])
        elif name not in missing:
            missing.append(name)
    else:
        rendered.append(part)

if missing:
    print('ERROR missing: ' + ', '.join(missing))
else:
    print(''.join(rendered))
unused = sorted(set(values) - used)
if unused:
    print('WARNING unused: ' + ', '.join(unused))
